    /// Called by the socket task after a successful WebSocket write.
    /// Accounting clears only when no frames remain in channel or pending.
    pub async fn note_frame_sent(&self, connection_id: &[u8]) {
        {
            let sockets = self.sockets.lock().await;
            let Some(live) = sockets.get(connection_id) else {
                return;
            };
            live.inflight.fetch_sub(1, Ordering::AcqRel);
            // Hold sockets across the zero-check and drain so try_deliver cannot
            // admit another frame that would then be cleared incorrectly.
            if live.inflight.load(Ordering::Acquire) == 0 {
                let mut fanout = self.fanout.lock().await;
                if let Some(connection) = fanout.get_mut(connection_id) {
                    connection.queue.drain_all();
                }
            }
        }
        self.flush_pending(connection_id).await;
    }

    async fn flush_pending(&self, connection_id: &[u8]) {
        let sockets = self.sockets.lock().await;
        let Some(live) = sockets.get(connection_id) else {
            return;
        };
        let mut pending = live
            .pending
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        while let Some(frame) = pending.pop_front() {
            match live.outbound_tx.try_send(frame.clone()) {
                Ok(()) => {}
                Err(_) => {
                    pending.push_front(frame);
                    break;
                }
            }
        }
    }

    /// Deliver one frame without awaiting. Returns true if accepted by the channel
    /// or buffered in the bounded pending deque. When pending is full, the oldest
    /// pending frame is evicted so the newest (especially command results) is kept.
    /// Snapshot byte-cap accounting stays in the fan-out publish path; command
    /// results must call [`OutboundQueue::enqueue_event`] before this.
    async fn try_deliver(&self, connection_id: &[u8], frame: Bytes) -> bool {
        let sockets = self.sockets.lock().await;
        let Some(live) = sockets.get(connection_id) else {
            return false;
        };
        match live.outbound_tx.try_send(frame.clone()) {
            Ok(()) => {
                live.inflight.fetch_add(1, Ordering::AcqRel);
                true
            }
            Err(_) => {
                let mut pending = live
                    .pending
                    .lock()
                    .unwrap_or_else(std::sync::PoisonError::into_inner);
                if pending.len() >= OUTBOUND_CHANNEL_CAP {
                    // Evict oldest undelivered frame; keep newest. Inflight count
                    // unchanged (one out, one in).
                    let _ = pending.pop_front();
                    pending.push_back(frame);
                } else {
                    pending.push_back(frame);
                    live.inflight.fetch_add(1, Ordering::AcqRel);
                }
                true
            }
        }
    }
}

/// Summary of one non-blocking drain pass.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DrainReport {
    pub delivered: usize,
    pub closed: Vec<Vec<u8>>,
    /// Connections whose AOI policy could not produce an interest set this
    /// pass, with the typed reason. They were skipped rather than sent an
    /// untruncated payload, so the drain reports them instead of leaving the
    /// starvation silent.
    pub interest_unavailable: Vec<(Vec<u8>, AoiError)>,
}

}

impl OutboundQueue {
    #[must_use]
    pub fn new() -> Self {
        Self::default()
    }

    #[must_use]
    pub fn is_closed(&self) -> bool {
        self.closed
    }

    #[must_use]
    pub fn over_limit_ticks(&self) -> u32 {
        self.over_limit_ticks
    }

    #[must_use]
    pub fn queued_bytes(&self) -> usize {
        self.state_bytes() + self.event_bytes
    }

    #[must_use]
    pub fn state_bytes(&self) -> usize {
        self.state_items.iter().map(|item| item.bytes).sum()
    }

    /// Enqueue replaceable state. When coalescing would drop a prior full snapshot
    /// and leave only a delta, the newest item is promoted to a full snapshot using
    /// `full_encoded_bytes` so the queue remains self-contained.
    pub fn enqueue_state(
        &mut self,
        encoded_bytes: usize,
        kind: StateKind,
        full_encoded_bytes: usize,
    ) -> Option<EnqueueStateOutcome> {
        if self.closed {
            return None;
        }
        let mut candidate_items = self.state_items.clone();
        candidate_items.push(StateItem {
            bytes: encoded_bytes,
            kind,
        });
        let candidate_bytes: usize =
            candidate_items.iter().map(|item| item.bytes).sum::<usize>() + self.event_bytes;
        let coalesced = candidate_bytes > QUEUE_LIMIT_BYTES && candidate_items.len() > 1;
        let mut newest = StateItem {
            bytes: encoded_bytes,
            kind,
        };
        if coalesced {
            let dropped_full = self
                .state_items
                .iter()
                .any(|item| item.kind == StateKind::Full);
            if dropped_full && newest.kind == StateKind::Delta {
                newest = StateItem {
                    bytes: full_encoded_bytes,
                    kind: StateKind::Full,
                };
            }
            self.state_items = vec![newest];
        } else {
            self.state_items = candidate_items;
        }
        let queued_bytes = self.queued_bytes();
        Some(EnqueueStateOutcome {
            coalesced,
            queued_bytes,
            over_limit: queued_bytes > QUEUE_LIMIT_BYTES,
            kind: self
                .state_items
                .last()
                .map(|item| item.kind)
                .unwrap_or(kind),
        })
    }

    /// Enqueue a non-coalesced event/result frame into byte accounting.
    pub fn enqueue_event(&mut self, encoded_bytes: usize) -> bool {
        if self.closed {
            return false;
        }
        self.event_bytes = self.event_bytes.saturating_add(encoded_bytes);
        true
    }

    /// Clear event-byte accounting after those frames have been written.
    pub fn drain_events(&mut self) {
        if !self.closed {
            self.event_bytes = 0;
        }
    }

    /// Drain replaceable state (models a successful socket write of current state).
    pub fn drain_state(&mut self) {
        if !self.closed {
            self.state_items.clear();
        }
    }

    /// Clear all replaceable state and event accounting (socket fully caught up).
    pub fn drain_all(&mut self) {
        if !self.closed {
            self.state_items.clear();
            self.event_bytes = 0;
        }
    }

