/// Advance the authoritative world one tick and clone what it published.
async fn advance_and_publish(state: &TransportState) -> ImmutableGeneration {
    let mut world = state.world.lock().await;
    world.advance_tick().expect("advance one tick");
    world
        .last_generation()
        .expect("published generation")
        .clone()
}

#[tokio::test]
async fn live_viewer_snapshot_truncates_to_the_hard_cap_nearest_first() {
    let (state, url) = start_server().await;
    let (mut viewer, _hello) = connect(&url, ConnectionRole::Viewer, b"").await;

    let generation = crowd_generation(1);
    assert!(
        generation.active_leases.len() > hard_cap(),
        "the crowd must exceed the hard cap or this test asserts nothing"
    );
    state.publish_generation(generation.clone());
    let report = state.drain_fanout(None).await;
    assert_eq!(report.delivered, 1, "the viewer should receive one frame");

    let (is_full, delivered) = next_state_body_ids(&mut viewer, &[]).await;
    assert!(is_full, "the first observe frame is a full snapshot");
    assert_eq!(
        delivered.len(),
        hard_cap(),
        "a live viewer snapshot must be truncated to the AOI hard cap"
    );
    assert_eq!(
        delivered,
        expected_interest(&generation, WORLD_ORIGIN, hard_cap()),
        "delivered bodies must be the nearest-first survivors for the viewer focus"
    );
}

#[tokio::test]
async fn live_aigent_interest_ranks_from_its_own_body() {
    let (state, url) = start_server().await;
    let aigent_id = b"aoi-focus-aigent".to_vec();
    let (mut aigent, hello) = connect(&url, ConnectionRole::Aigent, &aigent_id).await;

    // Take the aigent's own body from authoritative state rather than
    // re-deriving the server's aigent�+'body mapping: issue a real MOVE, advance
    // the world, and read back the lease the world granted to this aigent.
    move_and_confirm(&mut aigent, &hello, b"aoi-focus-move").await;
    let published = advance_and_publish(&state).await;
    let mut owned: Vec<LeaseSnapshot> = published
        .active_leases
        .values()
        .filter(|lease| lease.aigent_id == aigent_id)
        .cloned()
        .collect();
    assert_eq!(
        owned.len(),
        1,
        "the move should grant this aigent exactly one body"
    );
    let own_lease = owned.pop().expect("checked length");
    let own_body = own_lease.body_id;

    let generation = generation_of(2, CROWD.map(lease).chain(std::iter::once(own_lease)));
    let from_own_body = expected_interest(&generation, pose_of(&generation, own_body), hard_cap());
    let from_origin = expected_interest(&generation, WORLD_ORIGIN, hard_cap());
    assert_ne!(
        from_own_body, from_origin,
        "fixture must separate the aigent's body from the origin, or the test proves nothing"
    );

    state.publish_generation(generation.clone());
    let report = state.drain_fanout(None).await;
    assert_eq!(report.delivered, 1);

    let (is_full, delivered) = next_state_body_ids(&mut aigent, &[]).await;
    assert!(is_full, "the first observe frame is a full snapshot");
    assert_eq!(
        delivered.first().copied(),
        Some(own_body),
        "an aigent's own body is at distance zero from its focus"
    );
    assert_eq!(
        delivered, from_own_body,
        "aigent interest must rank against its own body, not the world origin"
    );
}

#[tokio::test]
async fn bodies_leaving_the_interest_set_stop_appearing_in_deltas() {
    let (state, url) = start_server().await;
    let (mut viewer, _hello) = connect(&url, ConnectionRole::Viewer, b"").await;

    let first = crowd_generation(1);
    state.publish_generation(first.clone());
    let _ = state.drain_fanout(None).await;
    let (is_full, delivered_first) = next_state_body_ids(&mut viewer, &[]).await;
    assert!(is_full, "the first observe frame is a full snapshot");
    assert_eq!(
        delivered_first,
        expected_interest(&first, WORLD_ORIGIN, hard_cap())
    );

    // A band of bodies nearer the viewer focus displaces part of the crowd.
    let second = generation_of(2, CROWD.chain(NEAR_ORIGIN_BAND).map(lease));
    let expected_second = expected_interest(&second, WORLD_ORIGIN, hard_cap());
    let leaving: Vec<u64> = delivered_first
        .iter()
        .copied()
        .filter(|body_id| !expected_second.contains(body_id))
        .collect();
    assert!(
        !leaving.is_empty(),
        "fixture must evict at least one body, or the leave assertion is vacuous"
    );

    state.publish_generation(second.clone());
    let _ = state.drain_fanout(None).await;
    let (is_full, delivered_second) = next_state_body_ids(&mut viewer, &delivered_first).await;
    assert!(
        !is_full,
        "an established baseline should be followed by a delta"
    );
    // The new real-body delta carries explicit enter/modify/leave records, not
    // a full body list. After the test helper applies the diff to the prior
    // set, the cumulative set must match the expected AOI rank; the helper
    // returns it in ascending order, so compare via a sorted equal.
    let mut sorted_second = delivered_second.clone();
    sorted_second.sort();
    let mut sorted_expected = expected_second.clone();
    sorted_expected.sort();
    assert_eq!(
        sorted_second, sorted_expected,
        "after applying the delta, the cumulative interest set must match the truncated baseline"
    );
    for body_id in leaving {
        assert!(
            !sorted_second.contains(&body_id),
            "body {body_id} left the interest set and must stop being delivered"
        );
    }
}

#[tokio::test]
async fn client_resync_baseline_is_truncated() {
    // The socket handler delegates a SnapshotResyncRequest straight to
    // `SnapshotFanout::client_resync`, so this exercises the resync payload the
    // wire carries. Driving it here lets the world hold more bodies than the
    // cap, which the demo world cannot yet reach through commands alone.

#[tokio::test]
async fn queued_bytes_equal_the_snapshot_frame_the_socket_receives() {
    let (state, url) = start_server().await;
    let (mut viewer, hello) = connect(&url, ConnectionRole::Viewer, b"").await;
    // Hold the writer: the accounting clears as soon as the socket reports the
    // write, so the queue has to be read while it still owes the frame.
    pause_writer(&state, &mut viewer, &hello.connection_id).await;

    let generation = crowd_generation(1);
    assert!(
        generation.active_leases.len() > hard_cap(),
        "the crowd must exceed the hard cap or the per-body undercount is invisible"
    );
    state.publish_generation(generation);
    state.advance_logical_tick();
    let report = state.drain_fanout(None).await;
    assert_eq!(report.delivered, 1, "the viewer should be queued one frame");

    let queued = queued_bytes(&state, &hello.connection_id).await;

    resume_writer(&state, &mut viewer, &hello.connection_id).await;
    let frame = next_binary_frame(&mut viewer).await;
    let (is_full, bodies) = state_frame_bodies(&frame);
    assert!(is_full, "the first observe frame is a full snapshot");
    assert_eq!(
        bodies.len(),
        hard_cap(),
        "the delivered frame must carry a full-cap interest set"
    );
    assert_eq!(
        queued,
        frame.len(),
        "outbound pressure must be charged the bytes the socket actually received"
    );
}

#[tokio::test]
async fn delta_frames_are_charged_their_wire_bytes() {
    let (state, url) = start_server().await;
    let (mut viewer, hello) = connect(&url, ConnectionRole::Viewer, b"").await;

    // Establish a baseline so the next publish is a delta.
    state.publish_generation(crowd_generation(1));
    state.advance_logical_tick();
    assert_eq!(state.drain_fanout(None).await.delivered, 1);
    let (is_full, _) = state_frame_bodies(&next_binary_frame(&mut viewer).await);
    assert!(is_full, "the baseline frame is a full snapshot");
    wait_for_empty_queue(&state, &hello.connection_id).await;

    pause_writer(&state, &mut viewer, &hello.connection_id).await;
    state.publish_generation(crowd_generation(2));
    state.advance_logical_tick();
    assert_eq!(state.drain_fanout(None).await.delivered, 1);
    let queued = queued_bytes(&state, &hello.connection_id).await;

    resume_writer(&state, &mut viewer, &hello.connection_id).await;
    let frame = next_binary_frame(&mut viewer).await;
    let (is_full, _bodies) = state_frame_bodies(&frame);
    assert!(!is_full, "an established baseline is followed by a delta");
    // The real-body delta carries only the explicit enter/leave records; the
    // prior full set is recoverable by the receiver from the baseline plus
    // the delta. The accounting assertion is the load-bearing one: queued
    // bytes must equal the frame the socket actually receives.
    assert_eq!(
        queued,
        frame.len(),
        "a delta must be charged its encoded frame, not a logical stand-in"
    );
}

#[tokio::test]
async fn paused_writer_reaches_the_coalesce_threshold_on_its_real_frame_bytes() {
    let (state, url) = start_server().await;
    let (mut viewer, hello) = connect(&url, ConnectionRole::Viewer, b"").await;

    // Measure one real frame for this connection before applying any pressure.
    state.publish_generation(crowd_generation(1));
    state.advance_logical_tick();
    assert_eq!(state.drain_fanout(None).await.delivered, 1);
    let frame_bytes = next_binary_frame(&mut viewer).await.len();
    wait_for_empty_queue(&state, &hello.connection_id).await;

    // Derived expectation: how many frames of that size the documented 256 KiB
    // threshold admits before the queue must coalesce.
    let expected_drains = QUEUE_LIMIT_BYTES.div_ceil(frame_bytes);
    assert!(
        expected_drains > 1,
        "one frame must not already exceed the limit, or coalescing proves nothing"
    );

    pause_writer(&state, &mut viewer, &hello.connection_id).await;
    let mut owed = 0usize;
    let mut peak = 0usize;
    let mut coalesced_at = None;
    let mut closed = false;
    let mut last_frame_bytes = frame_bytes;
    for drain in 1..=(expected_drains * 3 + 2) {
        let mut g = crowd_generation_with_offset(1 + drain as u64, drain as u64);
        for entity in g.entities.values_mut() {
            entity.revision = entity.revision.saturating_add(1);
        }
        state.publish_generation(g);
        state.advance_logical_tick();
        let report = state.drain_fanout(None).await;
        closed |= report.closed.iter().any(|id| id == &hello.connection_id);
        let queued = queued_bytes(&state, &hello.connection_id).await;
        if queued < owed {
            peak = owed;
            coalesced_at = Some(drain);
            break;
        }
        last_frame_bytes = queued.saturating_sub(owed).max(0);
        owed = queued;
    }

    let coalesced_at = coalesced_at.expect(
        "a paused writer must reach the 256 KiB threshold once it is charged the bytes it owes",
    );
    assert!(
        (expected_drains - 1..=expected_drains + 1).contains(&coalesced_at),
        "coalescing happened at drain {coalesced_at}, but {frame_bytes}-byte frames imply \
         drain {expected_drains}"
    );
    assert!(
        peak + last_frame_bytes > QUEUE_LIMIT_BYTES,
        "the queue must actually reach the threshold before coalescing, not merely shrink"
    );
    assert!(
        peak <= QUEUE_LIMIT_BYTES,
        "coalescing must keep queued state at or under the documented limit"
    );
    assert!(
        !closed,
        "coalescing under the cap must isolate no connection; only sustained over-limit \
         pressure disconnects"
    );
}

#[tokio::test]
async fn coalescing_charges_the_promoted_full_snapshot_it_writes() {
    let (state, url) = start_server().await;
    let (mut viewer, hello) = connect(&url, ConnectionRole::Viewer, b"").await;
    // Paused before the first frame, so the queued full snapshot is still there
    // when coalescing has to drop it and promote the newest delta. That is the
    // branch that charges the promoted frame rather than the delta.
    pause_writer(&state, &mut viewer, &hello.connection_id).await;

    state.publish_generation(crowd_generation(1));
    state.advance_logical_tick();
    assert_eq!(state.drain_fanout(None).await.delivered, 1);
    let first_charge = queued_bytes(&state, &hello.connection_id).await;
    assert!(first_charge > 0, "the baseline frame must be charged");

    let mut owed = first_charge;
    let mut promoted = false;
    for drain in 2..=(QUEUE_LIMIT_BYTES.div_ceil(first_charge) * 3 + 10) {
        let mut g = crowd_generation_with_offset(drain as u64, drain as u64 - 1);
        for entity in g.entities.values_mut() {
            entity.revision = entity.revision.saturating_add(1);
        }
        state.publish_generation(g);
        state.advance_logical_tick();
        assert_eq!(state.drain_fanout(None).await.delivered, 1);
        let queued = queued_bytes(&state, &hello.connection_id).await;
        if queued < owed {
            promoted = true;
            break;
        }
        owed = queued;
    }
    assert!(promoted, "the queue must coalesce once it passes the limit");
    let promoted_charge = queued_bytes(&state, &hello.connection_id).await;

    resume_writer(&state, &mut viewer, &hello.connection_id).await;
    let frames = drain_socket_frames(&mut viewer).await;
    assert!(frames.len() >= 2, "the socket owed at least two frames");

    let baseline_frame = frames.first().expect("checked length");
    let (is_full, _) = state_frame_bodies(baseline_frame);
    assert!(is_full, "the oldest queued frame is the baseline snapshot");
    assert_eq!(
        first_charge,
        baseline_frame.len(),
        "the baseline frame must be charged the bytes it puts on the wire"
    );

    let promoted_frame = frames.last().expect("checked length");
    let envelope = Envelope::decode(promoted_frame.as_slice()).expect("envelope");
    let Some(envelope::Body::FullSnapshot(full)) = envelope.body else {
        panic!("a coalesce that drops the queued snapshot must promote to a full snapshot");
    };
    assert!(
        full.baseline_id > 1,
        "the promotion must install a fresh baseline, got {}",
        full.baseline_id
    );
    let bodies = decode_world_snapshot_body_ids(&full.payload).expect("real-body snapshot payload");
    assert_eq!(
        bodies.len(),
        hard_cap(),
        "the promoted snapshot still carries a full-cap interest set"
    );
    assert_eq!(
        promoted_charge,
        promoted_frame.len(),
        "a promoted full snapshot must be charged the promoted frame it writes"
    );
}

